function DataIntegration() {
  const [xeroConnected, setXeroConnected] = React.useState(false);
  const [bankConnected, setBankConnected] = React.useState(false);

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gray-100">
      <div className="bg-white shadow-md rounded-lg p-8 max-w-md w-full">
        <h2 className="text-2xl font-semibold text-gray-800 mb-4">Data Integration</h2>

        <div className="mb-4">
          <label className="block text-gray-700 text-sm font-bold mb-2">Connect to Xero:</label>
          <button
            onClick={() => setXeroConnected(!xeroConnected)}
            className={`bg-${xeroConnected ? 'green' : 'blue'}-500 hover:bg-${xeroConnected ? 'green' : 'blue'}-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline`}
          >
            {xeroConnected ? 'Connected' : 'Connect'}
          </button>
        </div>

        <div className="mb-4">
          <label className="block text-gray-700 text-sm font-bold mb-2">Connect to Bank (CDR):</label>
          <button
            onClick={() => setBankConnected(!bankConnected)}
            className={`bg-${bankConnected ? 'green' : 'blue'}-500 hover:bg-${bankConnected ? 'green' : 'blue'}-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline`}
          >
            {bankConnected ? 'Connected' : 'Connect'}
          </button>
        </div>

        <div className="mb-4">
          <p className="text-gray-600 text-sm">Data Import Status: <span className="font-semibold">{xeroConnected && bankConnected ? 'Complete' : 'Pending'}</span></p>
        </div>
        <button className="bg-gray-300 hover:bg-gray-400 text-gray-800 font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline">
            Next
          </button>
      </div>
    </div>
  );
}

function UserManagement() {
  const [users, setUsers] = React.useState([
    { id: 1, name: 'John Doe', role: 'Admin', twoFactorEnabled: true },
    { id: 2, name: 'Jane Smith', role: 'Manager', twoFactorEnabled: false },
    { id: 3, name: 'Peter Jones', role: 'User', twoFactorEnabled: false },
  ]);

  const toggleTwoFactor = (userId) => {
    setUsers(users.map(user => user.id === userId ? { ...user, twoFactorEnabled: !user.twoFactorEnabled } : user));
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gray-100">
      <div className="bg-white shadow-md rounded-lg p-8 max-w-4xl w-full">
        <h2 className="text-2xl font-semibold text-gray-800 mb-4">User Management and Security</h2>

        <h3 className="text-xl font-semibold text-gray-700 mb-2">User List</h3>
        <table className="table-auto w-full mb-6">
          <thead>
            <tr className="bg-gray-200">
              <th className="px-4 py-2">Name</th>
              <th className="px-4 py-2">Role</th>
              <th className="px-4 py-2">Two-Factor Authentication</th>
              <th className="px-4 py-2">Actions</th>
            </tr>
          </thead>
          <tbody>
            {users.map(user => (
              <tr key={user.id}>
                <td className="border px-4 py-2">{user.name}</td>
                <td className="border px-4 py-2">{user.role}</td>
                <td className="border px-4 py-2">{user.twoFactorEnabled ? 'Enabled' : 'Disabled'}</td>
                <td className="border px-4 py-2">
                  <button
                    onClick={() => toggleTwoFactor(user.id)}
                    className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-1 px-2 rounded focus:outline-none focus:shadow-outline"
                  >
                    {user.twoFactorEnabled ? 'Disable' : 'Enable'}
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        <h3 className="text-xl font-semibold text-gray-700 mb-2">Role Management</h3>
        <p className="text-gray-600 mb-4">[Placeholder for Role Management UI]</p>

      </div>
    </div>
  );
}

