import React, { useState, useEffect } from 'react';

const FlowWisePrototype = () => {
  const [connectionStatus, setConnectionStatus] = useState('idle'); // 'idle', 'connecting', 'connected'
  const [activeIntegration, setActiveIntegration] = useState(null);
  const [showForecast, setShowForecast] = useState(false);

  const integrations = [
    {
      id: 'xero',
      name: 'Xero',
      description: 'Accounting software for small businesses.',
      logo: (
        <svg viewBox="0 0 32 32" className="h-10 w-10"><path fill="#14B8A6" d="M32 16c0 8.837-7.163 16-16 16S0 24.837 0 16 7.163 0 16 0s16 7.163 16 16"/><path fill="#FFF" d="m23.363 10.125-4.433 7.025 4.433 7.025h-3.433l-2.71-4.322-2.73 4.322H11.06l4.43-7.025L11.06 10.125h3.433l2.71 4.322 2.73-4.322z"/></svg>
      ),
    },
    {
      id: 'myob',
      name: 'MYOB',
      description: 'Business management solutions in AU & NZ.',
      logo: (
         <svg viewBox="0 0 24 24" className="h-10 w-10"><path fill="#FF4500" d="M12,2A10,10 0 0,0 2,12A10,10 0 0,0 12,22A10,10 0 0,0 22,12A10,10 0 0,0 12,2M12,4A8,8 0 0,1 20,12A8,8 0 0,1 12,20A8,8 0 0,1 4,12A8,8 0 0,1 12,4M11,6V8H8V18H10V14H11V18H13V14H14V18H16V8H13V12H11V6H11Z"/></svg>
      ),
    },
    {
      id: 'quickbooks',
      name: 'QuickBooks',
      description: 'Manage accounting, payroll, and payments.',
      logo: (
        <svg viewBox="0 0 24 24" className="h-10 w-10"><path fill="#2CA01C" d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1.2 15.6c-.44.44-1.16.44-1.6 0l-3.2-3.2c-.44-.44-.44-1.16 0-1.6s1.16-.44 1.6 0l2.4 2.4 5.6-5.6c.44-.44 1.16-.44 1.6 0s.44 1.16 0 1.6l-6.4 6.4z"/></svg>
      ),
    },
  ];

  const forecastData = {
    summary: {
        startingBalance: 125430.50,
        netCashFlow: 35210.80,
        endingBalance: 160641.30,
        lowestPoint: 98750.00,
    },
    weekly: [
        { week: 1, forecast: 135000, confidence: [128000, 142000] },
        { week: 2, forecast: 142000, confidence: [130000, 150000] },
        { week: 3, forecast: 118000, confidence: [105000, 125000] },
        { week: 4, forecast: 98750, confidence: [90000, 110000] },
        { week: 5, forecast: 115000, confidence: [108000, 128000] },
        { week: 6, forecast: 122000, confidence: [115000, 135000] },
        { week: 7, forecast: 148000, confidence: [139000, 160000] },
        { week: 8, forecast: 160641, confidence: [152000, 171000] },
    ]
  };

  const handleConnect = (integrationId) => {
    if (connectionStatus === 'connecting') return;
    setActiveIntegration(integrationId);
    setConnectionStatus('connecting');
    setTimeout(() => {
      setConnectionStatus('connected');
      setTimeout(() => {
        setShowForecast(true);
      }, 1200);
    }, 2500);
  };

  const handleDisconnect = () => {
    setShowForecast(false);
    setTimeout(() => {
        setConnectionStatus('idle');
        setActiveIntegration(null);
    }, 500); // allow for fade out animation
  }

  const ConnectionScreen = () => (
    <div className="max-w-3xl mx-auto">
        <div className="text-center mb-10">
            <h2 className="text-3xl font-bold text-slate-800">Connect Your Financial Data</h2>
            <p className="mt-2 text-lg text-slate-500">Securely link your accounting software to get started.</p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {integrations.map((int) => (
                <div key={int.id} className="bg-white rounded-xl border border-slate-200 shadow-sm p-6 flex flex-col items-center text-center transition-all duration-300 hover:shadow-lg hover:-translate-y-1">
                    <div className="mb-4">{int.logo}</div>
                    <h3 className="text-xl font-semibold text-slate-800 mb-1">{int.name}</h3>
                    <p className="text-slate-500 text-sm flex-grow mb-6">{int.description}</p>
                    <button 
                        onClick={() => handleConnect(int.id)} 
                        disabled={connectionStatus === 'connecting'}
                        className={`w-full px-4 py-2.5 rounded-lg font-semibold text-white transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 ${activeIntegration === int.id ? 'bg-emerald-500' : 'bg-blue-600 hover:bg-blue-700 focus:ring-blue-500'} disabled:bg-slate-300 disabled:cursor-not-allowed`}
                    >
                        {connectionStatus === 'connecting' && activeIntegration === int.id ? (
                            <span className="flex items-center justify-center">
                                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                                Connecting...
                            </span>
                        ) : connectionStatus === 'connected' && activeIntegration === int.id ? (
                             <span className="flex items-center justify-center">
                                <svg className="-ml-1 mr-2 h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                                Connected
                            </span>
                        ) : 'Connect'}
                    </button>
                </div>
            ))}
        </div>
         <div className="text-center mt-8 text-sm text-slate-400 flex items-center justify-center">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-2" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z" clipRule="evenodd" /></svg>
            Bank-level security. Your data is encrypted and secure.
        </div>
    </div>
  );

  const StatCard = ({ title, value, change, isCurrency = true }) => (
    <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
        <p className="text-sm font-medium text-slate-500">{title}</p>
        <p className="text-3xl font-bold text-slate-800 mt-2">{isCurrency ? `$${value.toLocaleString('en-AU')}` : value}</p>
        {change && <p className={`mt-1 text-sm font-medium ${change > 0 ? 'text-emerald-600' : 'text-red-600'}`}>{change > 0 ? '↑' : '↓'} {Math.abs(change)}% vs last period</p>}
    </div>
  );

  const ForecastChart = () => {
    const maxVal = Math.max(...forecastData.weekly.map(w => w.confidence[1]));
    return (
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
            <h3 className="text-lg font-semibold text-slate-800 mb-4">Weekly Forecast Balance</h3>
            <div className="flex justify-between items-end h-64 space-x-2">
                {forecastData.weekly.map(week => {
                    const barHeight = (week.forecast / maxVal) * 100;
                    const confidenceTop = (week.confidence[1] / maxVal) * 100;
                    const confidenceBottom = (week.confidence[0] / maxVal) * 100;
                    return (
                        <div key={week.week} className="flex-1 flex flex-col justify-end items-center group">
                            <div className="relative w-full h-full flex justify-center items-end">
                                <div className="absolute bg-blue-200 opacity-60 rounded-t-md" style={{ height: `${confidenceTop - confidenceBottom}%`, bottom: `${confidenceBottom}%`, width: '60%' }}></div>
                                <div className="relative bg-blue-500 rounded-t-md z-10" style={{ height: `${barHeight}%`, width: '60%' }}></div>
                                <div className="absolute -top-8 bg-slate-700 text-white text-xs font-bold px-2 py-1 rounded-md opacity-0 group-hover:opacity-100 transition-opacity duration-200">${Math.round(week.forecast / 1000)}k</div>
                            </div>
                            <p className="text-xs text-slate-500 mt-2">Wk {week.week}</p>
                        </div>
                    )
                })}
            </div>
        </div>
    )
  }

  const ForecastScreen = () => (
    <div className={`transition-opacity duration-500 ${showForecast ? 'opacity-100' : 'opacity-0'}`}>
        <div className="flex justify-between items-center mb-8">
            <div>
                <h2 className="text-3xl font-bold text-slate-800">Cash Flow Forecast</h2>
                <p className="mt-1 text-lg text-slate-500">Next 90 days, based on your Xero data.</p>
            </div>
            <button onClick={handleDisconnect} className="bg-slate-200 text-slate-700 font-semibold px-4 py-2 rounded-lg hover:bg-slate-300 transition-colors">Manage Connections</button>
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 mb-6">
            <StatCard title="Starting Balance" value={forecastData.summary.startingBalance} />
            <StatCard title="Net Cash Flow" value={forecastData.summary.netCashFlow} change={15} />
            <StatCard title="Forecasted End Balance" value={forecastData.summary.endingBalance} />
            <StatCard title="Lowest Point Forecast" value={forecastData.summary.lowestPoint} />
        </div>
        <ForecastChart />
        <div className="mt-6 p-4 bg-amber-50 border-l-4 border-amber-400 rounded-r-lg">
            <div className="flex">
                <div className="flex-shrink-0">
                    <svg className="h-5 w-5 text-amber-400" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true"><path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 3.001-1.742 3.001H4.42c-1.53 0-2.493-1.667-1.743-3.001l5.58-9.92zM10 13a1 1 0 110-2 1 1 0 010 2zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" /></svg>
                </div>
                <div className="ml-3">
                    <p className="text-sm text-amber-700"><b>Early Warning:</b> Potential cash shortfall in Week 4. <a href="#" className="font-medium underline text-amber-800 hover:text-amber-900">Model a scenario to mitigate.</a></p>
                </div>
            </div>
        </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-800">
      <header className="bg-white shadow-sm border-b border-slate-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex items-center justify-between">
          <div className="flex items-center space-x-3">
             <svg className="h-8 w-8 text-blue-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
             <h1 className="text-2xl font-bold text-slate-800">FlowWise</h1>
          </div>
          <div className="flex items-center space-x-4">
            <span className="text-sm text-slate-500">Alicia Chen</span>
            <img className="h-10 w-10 rounded-full" src="https://i.pravatar.cc/150?u=alicia-chen" alt="Alicia Chen" />
          </div>
        </div>
      </header>
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        {!showForecast ? <ConnectionScreen /> : <ForecastScreen />}
      </main>
    </div>
  );
};

export default FlowWisePrototype;

